<div class="heading"><div><div class="eyebrow">مخرجات جاهزة للمراجعة</div><h1>التقارير والطباعة</h1><p>خرائط وقوائم وتكليفات، مع PDF عربي وExcel بحفظ محلي.</p></div></div>
<section class="card"><form method="get"><input type="hidden" name="page" value="reports"><div class="grid"><?php $periods=rows('SELECT * FROM exam_periods WHERE institution_id=? AND year_id=? ORDER BY starts_at',[inst(),year_id()]);$periodOptions=[];foreach($periods as $r)$periodOptions[$r['id']]=$r['name'].' — '.$r['starts_at'];$periodId=(int)($_GET['period_id']??($periods[0]['id']??0));$type=$_GET['type']??'map';if(!isset(REPORT_TYPES[$type]))$type='map';selectf('الفترة الامتحانية','period_id',$periodOptions,$periodId);selectf('نوع التقرير','type',REPORT_TYPES,$type);selectf('حجم الورق','paper',['A4'=>'A4 أفقي','A3'=>'A3 أفقي'],$_GET['paper']??'A4');selectf('قاعة محددة — اختياري','room_id',opts('rooms','code'),$_GET['room_id']??'',false);$options=[];foreach(rows('SELECT id,name,code FROM students WHERE institution_id=? AND year_id=? ORDER BY name',[inst(),year_id()]) as $s)$options[$s['id']]=$s['code'].' — '.$s['name'];selectf('طالب محدد / بطاقة — اختياري','student_id',$options,$_GET['student_id']??'',false);?></div><div class="actions"><button>معاينة</button><button name="format" value="pdf" class="secondary">تنزيل PDF</button><button name="format" value="xlsx" class="secondary">تصدير Excel</button><button type="button" data-print class="ghost">طباعة المتصفح</button></div></form></section>
<?php if($periodId):$p=period($periodId);$data=report_data($p);?><section class="paper"><?=report_html($data,$type,(int)($_GET['room_id']??0),(int)($_GET['student_id']??0))?></section><?php else:?><div class="empty">أنشئ فترة امتحانية أولًا لإظهار التقارير.</div><?php endif;?>
